  `gallery` varchar(200) DEFAULT NULL,
  `productSize_length` varchar(100) DEFAULT NULL,
  `productSize_width` varchar(100) DEFAULT NULL,
  `productSize_height` varchar(100) DEFAULT NULL,
  `product_type` enum('simple','variant') DEFAULT NULL,
  `feature_price` varchar(50) DEFAULT NULL,
  `is_deleted` enum('0','1') DEFAULT NULL,
  `is_feature` enum('0','1') DEFAULT '0',
  `feature_startdate` date DEFAULT NULL,
  `feature_enddate` date DEFAULT NULL,
  `product_status` enum('1','2','3') DEFAULT NULL,
  `sales` int(11) DEFAULT 0,
  `product_currency` enum('cad','usd') DEFAULT NULL,
  `shipping_option_id` int(11) DEFAULT NULL,
