INSERT INTO `products` VALUES (93,6,3,'T-shirt','t-shirt','100% Cotton\r\n    Relaxed fit \r\n    Shrink-Less™ fabric - won\'t shrink in dryer \r\n    100% lightweight cotton jersey; heather colors: cotton/polyester\r\n    Machine wash; imported','<ul>\r\n	<li>100% Cotton</li>\r\n	<li>Relaxed fit&nbsp;</li>\r\n	<li>Shrink-Less&trade; fabric - won&#39;t shrink in dryer&nbsp;</li>\r\n	<li>100% lightweight cotton jersey; heather colors: cotton/polyester</li>\r\n	<li>Machine wash; imported</li>\r\n</ul>',20,NULL,45,'65689',3,'1',368,'a:0:{}','10','5','4','simple',NULL,NULL,'0',NULL,NULL,'1',61,NULL,NULL,0,60,2,35,'standard',NULL,NULL,1,0,'2018-11-20 12:09:52','2018-11-23 12:05:10'),(94,9,4,'Chanel Lipstick','chanel-lipstick','','<p>Worth Buying.</p>',89,NULL,34,'we',12,'1',312,'a:0:{}','12','43','11','simple',NULL,NULL,'0',NULL,NULL,'1',55,NULL,10,0,50,2,45,'standard','',NULL,1,0,'2018-11-20 12:32:41','2019-04-09 05:55:52'),(95,8,7,'Vintage squat square clear green glass','vintage-squat-square-clear-green-glass','This adorable bone-shaped dog tag is sure to get your pet noticed!','<p>&nbsp;The tag is made of solid copper, which makes it very sturdy but still light enough for medium and large dogs. The ID tag measures about 1.25 inches long and 1 inch wide at its widest point. For scale, this pet ID is slightly smaller than two U.S. quarters lined up next to each other.&nbsp;<br />\r\n&nbsp;</p>',500,NULL,0,NULL,4,'0',315,'a:3:{i:0;s:3:\"316\";i:1;s:3:\"317\";i:2;s:3:\"318\";}','50','80','100','simple',NULL,NULL,'0',NULL,NULL,'1',6,NULL,NULL,0,50,2,45,'all',NULL,NULL,0,0,'2018-11-20 12:40:52','2018-11-29 13:05:47'),(97,13,5,'Cat food','cat-food','','<ul>\r\n	<li>Contains One (1) 12-Lb Bag Of Blue Wilderness High Protein Grain Free Adult Dry Cat Food, Chicken</li>\r\n	<li>Always Features Real Meat As The 1St Ingredient. Made With Delicious, Protein-Rich, Deboned Chicken</li>\r\n	<li>We Use Only High-Quality Protein And Natural Sources Of Fiber To Help Provide Optimal Nutrient Absorption And Digestive Health, And An Optimal Balance Of Omega 3 & 6 Fatty Acids Helps Promote A Shiny Coat And Healthy Skin.</li>\r\n	<li>Provides the added protection of BLUE’s exclusive LifeSource Bits, a precise blend of vitamins, minerals and antioxidants.</li>\r\n	<li>Includes only the finest natural ingredients and contains NO chicken or poultry by-product meals, artificial preservatives, corn, wheat or soy.</li>\r\n	<li>A sensible alternative to a raw diet</li>\r\n</ul>',100,NULL,0,NULL,2.2,'1',322,'a:0:{}','20','10','10','simple',NULL,NULL,'0',NULL,NULL,'1',43,NULL,11,0,50,2,45,'all','',NULL,1,0,'2018-11-20 13:08:47','2019-02-14 13:10:44'),(98,6,3,'Buck Mmason T-shirt','buck-mmason-t-shirt','100% Cotton\r\nRelaxed fit \r\nShrink-Less™ fabric - won\'t shrink in dryer \r\n100% lightweight cotton jersey; heather colors: cotton/polyester\r\nMachine wash; imported','<ul>\r\n	<li>100% Cotton</li>\r\n	<li>Relaxed fit&nbsp;</li>\r\n	<li>Shrink-Less&trade; fabric - won&#39;t shrink in dryer&nbsp;</li>\r\n	<li>100% lightweight cotton jersey; heather colors: cotton/polyester</li>\r\n	<li>Machine wash; imported</li>\r\n</ul>',10,NULL,0,NULL,3,'1',370,'a:0:{}','10','5','4','variant',NULL,NULL,'0',NULL,NULL,'1',6,NULL,NULL,0,70,2,25,'all',NULL,NULL,0,0,'2018-11-20 13:18:12','2018-11-23 12:05:37'),(99,14,8,'Black Elephant Beads sale','black-elephant-beads-sale','','<p><strong>Lorem Ipsum</strong>&nbsp;is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry&#39;s standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book. It has survived not only five centuries, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.</p>',96