  `store_city` varchar(100) DEFAULT NULL,
  `street_address` varchar(500) DEFAULT NULL,
  `store_name` varchar(255) DEFAULT NULL,
  `store_slug` varchar(255) DEFAULT NULL,
  `zip_code` varchar(100) DEFAULT NULL,
  `store_logo` varchar(300) DEFAULT NULL,
  `contact_info` varchar(100) DEFAULT NULL,
  `store_status` enum('0','1','2') DEFAULT NULL,
  `is_completed` enum('0','1') DEFAULT NULL,
  `store_website` varchar(300) DEFAULT NULL,
  `store_fax_no` varchar(100) DEFAULT NULL,
  `latitude` varchar(50) DEFAULT NULL,
  `longitude` varchar(50) DEFAULT NULL,
  `about_store` text DEFAULT NULL,
  `policies` varchar(50) DEFAULT NULL,
  `store_suit` varchar(255) DEFAULT NULL,
  `terms_condtions` int(11) DEFAULT 0,
  `default_view` int(11) DEFAULT NULL,
  `store_icon` int(11) DEFAULT NULL,
