--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `user_id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `password` varchar(255) DEFAULT NULL,
  `login_key` varchar(100) NOT NULL,
  `remember_key` varchar(100) DEFAULT NULL,
  `forget_key` varchar(100) DEFAULT NULL,
  `forget_key_date` datetime DEFAULT NULL,
  `status` enum('0','1','2') NOT NULL DEFAULT '0',
  `has_store` enum('0','1') DEFAULT '0',
  `register_source` varchar(100) DEFAULT NULL,
  `ip_address` varchar(100) NOT NULL,
  `is_news_letter` int(11) DEFAULT 0,
  `user_avatar` int(11) DEFAULT NULL,
  `user_country_id` varchar(100) DEFAULT NULL,
  `user_state_id` varchar(100) DEFAULT NULL,
  `user_city_id` varchar(100) DEFAULT NULL,
  `user_zip_code` varchar(100) DEFAULT NULL,
  `contact_no` varchar(100) DEFAULT NULL,
  `physical_address` varchar(500) DEFAULT NULL,
  `zendesk_user_id` varchar(50) DEFAULT NULL,
  `about` text DEFAULT NULL,
  `user_credits` int(11) NOT NULL DEFAULT 0,
  `user_wallet` double NOT NULL DEFAULT 0,
  `email_alerts` int(11) DEFAULT 0,
  `sms_alerts` int(11) DEFAULT 0,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=102 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

